using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;

namespace Dafeiyu
{
    public static class Ui
    {
        public static readonly SolidColorBrush Ink = Brush("#203754"), Muted = Brush("#61738B"), Blue = Brush("#456DE6"), Pale = Brush("#EDF3FF"), Line = Brush("#DCE5F4"), Mint = Brush("#E8F5EF");
        private static Style buttonStyle;
        private static Style comboStyle,navigationStyle,fieldStyle,toggleStyle,passwordStyle,tooltipStyle;
        public static Style NavigationItemStyle {get{return navigationStyle;}}
        private static System.Windows.Media.Imaging.BitmapSource applicationIcon;
        public static System.Windows.Media.Imaging.BitmapSource ApplicationIcon()
        {
            if(applicationIcon==null)
                using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("Dafeiyu.Icon"))
                {
                    var decoder=System.Windows.Media.Imaging.BitmapDecoder.Create(stream,System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);
                    foreach(var frame in decoder.Frames)if(applicationIcon==null || frame.PixelWidth>applicationIcon.PixelWidth)applicationIcon=frame;
                    applicationIcon.Freeze();
                }
            return applicationIcon;
        }
        public static SolidColorBrush Brush(string hex) { var brush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); brush.Freeze(); return brush; }
        public static void Window(Window window, string title, double width, double height)
        {
            window.Title = title; window.Width = width; window.Height = height;window.Icon=ApplicationIcon();
            window.MinWidth = width - 40; window.MinHeight = Math.Min(430, height);
            window.MaxHeight = Math.Max(430, SystemParameters.WorkArea.Height - 36);
            window.FontFamily = new FontFamily("Microsoft YaHei UI"); window.FontSize = 13;
            window.Foreground = Ink; window.Background = Brush("#F7F9FD"); window.WindowStartupLocation = WindowStartupLocation.CenterScreen;
            SlimScrollBars.Install(window);window.UseLayoutRounding=true;window.SnapsToDevicePixels=true;
            if(tooltipStyle==null)tooltipStyle=(Style)XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='ToolTip'><Setter Property='Background' Value='White'/><Setter Property='Foreground' Value='#282A2F'/><Setter Property='BorderBrush' Value='#E1E4E8'/><Setter Property='BorderThickness' Value='1'/><Setter Property='Padding' Value='9,6'/><Setter Property='FontSize' Value='12'/><Setter Property='HasDropShadow' Value='True'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ToolTip'><Border Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='8' Padding='{TemplateBinding Padding}'><ContentPresenter/></Border></ControlTemplate></Setter.Value></Setter></Style>");
            window.Resources[typeof(ToolTip)]=tooltipStyle;if(Application.Current!=null)Application.Current.Resources[typeof(ToolTip)]=tooltipStyle;ToolTipService.SetInitialShowDelay(window,600);ToolTipService.SetShowDuration(window,3500);ToolTipService.SetBetweenShowDelay(window,250);            if(comboStyle==null)
            {
                comboStyle=(Style)XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='ComboBox'><Setter Property='FocusVisualStyle' Value='{x:Null}'/><Setter Property='Background' Value='White'/><Setter Property='BorderBrush' Value='#DCE5F4'/><Setter Property='Foreground' Value='#203754'/><Setter Property='ItemContainerStyle'><Setter.Value><Style TargetType='ComboBoxItem'><Setter Property='FocusVisualStyle' Value='{x:Null}'/><Setter Property='Padding' Value='9,5'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ComboBoxItem'><Border x:Name='item' Background='Transparent' CornerRadius='7' Padding='{TemplateBinding Padding}'><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property='IsHighlighted' Value='True'><Setter TargetName='item' Property='Background' Value='#EFEFEF'/></Trigger><Trigger Property='IsSelected' Value='True'><Setter TargetName='item' Property='Background' Value='#EAEAEA'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='0.45'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style></Setter.Value></Setter><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ComboBox'><Grid><ToggleButton Focusable='False' ClickMode='Press' IsChecked='{Binding IsDropDownOpen, RelativeSource={RelativeSource TemplatedParent}, Mode=TwoWay}'><ToggleButton.Template><ControlTemplate TargetType='ToggleButton'><Border Background='{Binding Background, RelativeSource={RelativeSource AncestorType=ComboBox}}' BorderBrush='{Binding BorderBrush, RelativeSource={RelativeSource AncestorType=ComboBox}}' BorderThickness='1' CornerRadius='9'><Path Data='M0,0 L4,4 L8,0' Stroke='#72839B' StrokeThickness='1.3' HorizontalAlignment='Right' VerticalAlignment='Center' Margin='0,0,14,0'/></Border></ControlTemplate></ToggleButton.Template></ToggleButton><ContentPresenter x:Name='selection' Content='{TemplateBinding SelectionBoxItem}' ContentTemplate='{TemplateBinding SelectionBoxItemTemplate}' Margin='12,7,36,7' VerticalAlignment='Center' IsHitTestVisible='False'/><TextBox x:Name='PART_EditableTextBox' Style='{x:Null}' Visibility='Hidden' IsReadOnly='{TemplateBinding IsReadOnly}' Foreground='{TemplateBinding Foreground}' Background='Transparent' BorderThickness='0' Padding='0' Margin='12,7,36,7' VerticalContentAlignment='Center' HorizontalContentAlignment='Left'/><Popup x:Name='PART_Popup' Placement='Bottom' IsOpen='{TemplateBinding IsDropDownOpen}' AllowsTransparency='True' Focusable='False' PopupAnimation='Slide'><Border Background='White' BorderBrush='#DCE5F4' BorderThickness='1' CornerRadius='9' MinWidth='{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}' Padding='4'><ScrollViewer MaxHeight='290' CanContentScroll='True'><ItemsPresenter KeyboardNavigation.DirectionalNavigation='Contained'/></ScrollViewer></Border></Popup></Grid><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter Property='Background' Value='#F1F1F1'/><Setter Property='BorderBrush' Value='#DADDE1'/></Trigger><Trigger Property='IsEditable' Value='True'><Setter TargetName='selection' Property='Visibility' Value='Hidden'/><Setter TargetName='PART_EditableTextBox' Property='Visibility' Value='Visible'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='0.5'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
                navigationStyle=(Style)XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='ListBoxItem'><Setter Property='FocusVisualStyle' Value='{x:Null}'/><Setter Property='Foreground' Value='#203754'/><Setter Property='Background' Value='Transparent'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ListBoxItem'><Border x:Name='surface' Background='{TemplateBinding Background}' CornerRadius='9' Padding='{TemplateBinding Padding}'><ContentPresenter VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter TargetName='surface' Property='Background' Value='#EFEFEF'/></Trigger><Trigger Property='IsSelected' Value='True'><Setter Property='Background' Value='#EAEAEA'/><Setter Property='Foreground' Value='#203754'/></Trigger><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='surface' Property='Background' Value='#EFEFEF'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
            }
            if(passwordStyle==null)passwordStyle=(Style)XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='PasswordBox'><Setter Property='FocusVisualStyle' Value='{x:Null}'/><Setter Property='Foreground' Value='#203754'/><Setter Property='BorderThickness' Value='1'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='PasswordBox'><Border x:Name='surface' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='9'><ScrollViewer x:Name='PART_ContentHost' Margin='{TemplateBinding Padding}'/></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter TargetName='surface' Property='Background' Value='#F3F3F3'/><Setter TargetName='surface' Property='BorderBrush' Value='#DADDE1'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='0.5'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
            window.Resources[typeof(ComboBox)]=comboStyle;window.Resources[typeof(PasswordBox)]=passwordStyle;
        }
        public static Button Button(string text, bool primary = false)
        {
            if (buttonStyle == null)
                buttonStyle = (Style)XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Button'><Setter Property='FocusVisualStyle' Value='{x:Null}'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='Button'><Grid x:Name='root'><Border Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1' CornerRadius='9'/><Border x:Name='highlight' Background='Transparent' CornerRadius='9'/><ContentPresenter Margin='{TemplateBinding Padding}' HorizontalAlignment='Center' VerticalAlignment='Center'/></Grid><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='highlight' Property='Background' Value='#10000000'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='highlight' Property='Background' Value='#10000000'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='highlight' Property='Background' Value='#20000000'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter TargetName='root' Property='Opacity' Value='0.45'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
            return new Button { Content = text, Style = buttonStyle, MinHeight = 36, Padding = new Thickness(13, 6, 13, 6),
                Background = primary ? Blue : Brushes.White, Foreground = primary ? Brushes.White : Ink,
                BorderBrush = primary ? Blue : Line, Cursor = System.Windows.Input.Cursors.Hand, FontWeight=primary?FontWeights.SemiBold:FontWeights.Normal, Margin = new Thickness(0, 0, 8, 0) };
        }
        public static TextBlock Text(string text, double size = 13, Brush color = null)
        { return new TextBlock { Text = text, FontSize = size, Foreground = color ?? Ink, TextWrapping = TextWrapping.Wrap, LineHeight = size * 1.65 }; }
        public static TextBox Field(string value = "", bool multiline = false)
        {
            if(fieldStyle==null)fieldStyle=(Style)XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='TextBox'><Setter Property='FocusVisualStyle' Value='{x:Null}'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='TextBox'><Border x:Name='surface' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='9'><ScrollViewer x:Name='PART_ContentHost' Margin='{TemplateBinding Padding}'/></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter TargetName='surface' Property='Background' Value='#F3F3F3'/><Setter TargetName='surface' Property='BorderBrush' Value='#DADDE1'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='0.5'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
            return new TextBox { Style=fieldStyle,Text = value ?? "", MinHeight = 38, Padding = new Thickness(10, 7, 10, 7), BorderBrush = Line, BorderThickness = new Thickness(1), Background = Brushes.White,Foreground=Ink,VerticalContentAlignment=multiline?VerticalAlignment.Top:VerticalAlignment.Center,
            TextWrapping = multiline ? TextWrapping.Wrap : TextWrapping.NoWrap, AcceptsReturn = multiline, VerticalScrollBarVisibility = multiline ? ScrollBarVisibility.Auto : ScrollBarVisibility.Hidden }; }
        public static Border Card(UIElement child)
        { return new Border { Child = child, Background = Brushes.White, CornerRadius = new CornerRadius(14), BorderBrush = Line, BorderThickness = new Thickness(1), Padding = new Thickness(18), Margin = new Thickness(0, 0, 0, 16) }; }
        public static void Label(Panel panel, string caption, UIElement field)
        {
            var label = Text(caption, 12, Ink); label.Margin = new Thickness(0, 12, 0, 6); panel.Children.Add(label); panel.Children.Add(field);
        }
        public static CheckBox Toggle(string label, bool value, Action<bool> changed)
        {
            if(toggleStyle==null)toggleStyle=(Style)XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='CheckBox'><Setter Property='FocusVisualStyle' Value='{x:Null}'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='CheckBox'><Border x:Name='highlight' CornerRadius='7' Background='Transparent' Padding='3'><StackPanel Orientation='Horizontal' Background='Transparent'><Border x:Name='track' Width='32' Height='20' CornerRadius='10' BorderThickness='1' BorderBrush='Transparent' Background='#CBD5E7' VerticalAlignment='Center' Margin='0,0,9,0'><Ellipse x:Name='thumb' Width='12' Height='12' Fill='White' HorizontalAlignment='Left' Margin='3,0,0,0'/></Border><ContentPresenter RecognizesAccessKey='True' VerticalAlignment='Center'/></StackPanel></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='highlight' Property='Background' Value='#EFEFEF'/></Trigger><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='highlight' Property='Background' Value='#EFEFEF'/></Trigger><Trigger Property='IsChecked' Value='True'><Setter TargetName='track' Property='Background' Value='#456DE6'/><Setter TargetName='thumb' Property='HorizontalAlignment' Value='Right'/><Setter TargetName='thumb' Property='Margin' Value='0,0,3,0'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='0.45'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
            var toggle = new CheckBox { Style=toggleStyle,Content = label, IsChecked = value, MinHeight=24,Margin = new Thickness(0, 6, 0, 9), VerticalContentAlignment = VerticalAlignment.Center };
            toggle.Checked += delegate { changed(true); }; toggle.Unchecked += delegate { changed(false); }; return toggle;
        }
        public static CheckBox ReplySpeechToggle(PetWindow pet)
        {
            var toggle=Toggle("TTS 输出",pet.Settings.ReadReplies,pet.SetReplySpeech);toggle.Name="TtsOutput";
            toggle.ToolTip="自动朗读文字回复和 ASR 对话回复。关闭会停止当前朗读。Live 音频由实时语音模式输出。";
            Action sync=()=>toggle.IsChecked=pet.Settings.ReadReplies;
            toggle.Loaded+=delegate {sync();pet.ReplySpeechChanged+=sync;};
            toggle.Unloaded+=delegate {pet.ReplySpeechChanged-=sync;};return toggle;
        }
        public static ScrollViewer Scroll(UIElement child) { return new ScrollViewer { Content = child, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled }; }
    }
}
